mapper.select:
SELECT pc.*, wo.order_no, wo.actual_quantity, wo.plan_quantity, p.product_name, p.product_code, pc2.category_name FROM production_cost pc LEFT JOIN work_order wo ON pc.work_order_id = wo.id LEFT JOIN product p ON pc.product_id = p.id LEFT JOIN product_category pc2 ON p.category_id = pc2.id
pc.deleted = 0
AND pc.cost_no LIKE CONCAT('%', #{costNo}, '%')
AND wo.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND p.product_name LIKE CONCAT('%', #{productName}, '%')
AND p.category_id = #{categoryId}
AND pc.status = #{status}
AND pc.cost_date >= #{startDate}
AND pc.cost_date <= #{endDate}
ORDER BY pc.create_time DESC

SELECT pc.cost_date, COUNT(*) AS cost_count, SUM(pc.total_cost) AS total_cost, SUM(pc.total_material_cost) AS total_material_cost, SUM(pc.total_mold_cost) AS total_mold_cost, SUM(pc.total_energy_cost) AS total_energy_cost, SUM(pc.total_labor_cost) AS total_labor_cost, SUM(pc.total_scrap_cost) AS total_scrap_cost, AVG(pc.unit_cost) AS avg_unit_cost, SUM(wo.actual_quantity) AS total_output FROM production_cost pc LEFT JOIN work_order wo ON pc.work_order_id = wo.id WHERE pc.deleted = 0 AND pc.status IN (1, 2)
AND pc.cost_date >= #{startDate}
AND pc.cost_date <= #{endDate}
AND pc.product_id = #{productId}
GROUP BY pc.cost_date ORDER BY pc.cost_date ASC

SELECT p.id AS product_id, p.product_name, p.product_code, COUNT(*) AS cost_count, SUM(pc.total_cost) AS total_cost, SUM(wo.actual_quantity) AS total_quantity, AVG(pc.unit_cost) AS avg_unit_cost, MIN(pc.unit_cost) AS min_unit_cost, MAX(pc.unit_cost) AS max_unit_cost FROM production_cost pc LEFT JOIN product p ON pc.product_id = p.id LEFT JOIN work_order wo ON pc.work_order_id = wo.id WHERE pc.deleted = 0 AND pc.status IN (1, 2)
AND pc.cost_date >= #{startDate}
AND pc.cost_date <= #{endDate}
GROUP BY p.id, p.product_name, p.product_code ORDER BY total_cost DESC
